  @override
  String get species_zebra_mussel_desc =>
      'Prążkowany małż wielkości paznokcia, tysiącami pokrywający skały, wraki i rury i oczyszczający wodę wszędzie tam, gdzie się rozprzestrzenia.';

  @override
  String get species_quagga_mussel_name => 'Racicznica bużańska';

  @override
  String get species_quagga_mussel_desc =>
      'Bardziej zaokrąglona i jaśniejsza krewna racicznicy zmiennej, zasiedlająca miękkie dno i głęboką zimną wodę, niedostępne dla tamtej.';

  @override
  String get species_freshwater_pearl_mussel_name => 'Perłoródka rzeczna';

  @override
  String get species_freshwater_pearl_mussel_desc =>
      'Ciemny, wydłużony małż, który może żyć ponad sto lat, do połowy zagrzebany w czystym żwirze bystrych rzek łososiowych.';

  @override
  String get species_swan_mussel_name => 'Szczeżuja wielka';

  @override
  String get species_swan_mussel_desc =>
      'Duży małż o cienkiej muszli z mulistych jezior i kanałów, filtrujący wodę syfonami tuż nad mułem.';

  @override
  String get species_chinese_pond_mussel_name => 'Szczeżuja chińska';

  @override
  String get species_chinese_pond_mussel_desc =>
      'Bardzo duży inwazyjny małż azjatycki o lśniącej brązowej muszli, zawleczony z rybami hodowlanymi i rozprzestrzeniający się w ciepłych jeziorach.';

  @override
  String get species_freshwater_sponge_name => 'Nadecznik stawowy';

  @override
  String get species_freshwater_sponge_desc =>
      'Zielona lub szara rozgałęziona gąbka porastająca patyki i kamienie w czystych jeziorach, zabarwiona przez żyjące w niej glony.';

  @override
  String get species_freshwater_jellyfish_name => 'Hederyka Rydera';

  @override
  String get species_freshwater_jellyfish_desc =>
      'Przezroczysta meduza wielkości monety, pojawiająca się późnym latem rojami w ciepłych jeziorach wyrobiskowych i zbiornikach zaporowych.';

  @override
  String get species_great_pond_snail_name => 'Błotniarka stawowa';

  @override
  String get species_great_pond_snail_desc =>
      'Duży ślimak o spiczastej muszli, sunący po roślinach i gładkich jak szkło powierzchniach stojących wód Europy i oddychający powietrzem przy powierzchni.';

  @override
  String get species_great_ramshorn_snail_name => 'Zatoczek rogowy';

  @override
  String get species_great_ramshorn_snail_desc =>
      'Płaski, spiralnie zwinięty ślimak przypominający maleńki barani róg, zgryzający glony z liści i kamieni w zarośniętych stawach.';

  @override
  String get species_channeled_apple_snail_name =>
      'Ampularia żłobkowana (channeled apple snail)';

  @override
  String get species_channeled_apple_snail_desc =>
      'Duży złotobrązowy ślimak składający jaskraworóżowe złoża jaj nad linią wody, inwazyjny na ciepłych mokradłach i polach ryżowych.';

  @override
  String get species_magnificent_bryozoan_name =>
      'Mszywiół wspaniały (magnificent bryozoan)';

  @override
  String get species_magnificent_bryozoan_desc =>
      'Galaretowata kolonia wielkości piłki nożnej, usiana maleńkimi zwierzętami, uczepiona gałęzi i lin w ciepłej stojącej wodzie.';

  @override
  String get species_chinese_mitten_crab_name => 'Krab wełnistoszczypcy';

  @override
  String get species_chinese_mitten_crab_desc =>
      'Ryjący nory krab o owłosionych szczypcach, który spędza lata w rzekach, zanim powędruje w dół rzeki, by rozmnażać się w estuariach.';

  @override
  String get species_giant_freshwater_prawn_name =>
      'Krewetka olbrzymia słodkowodna (giant freshwater prawn)';

  @override
  String get species_giant_freshwater_prawn_desc =>
      'Duża krewetka o niebieskich szczypcach z rzek Azji i Australii; u starych samców szczypce są dłuższe od ciała.';

  @override
  String get species_common_snapping_turtle_name => 'Skorpucha jaszczurowata';

  @override
  String get species_common_snapping_turtle_desc =>
      'Ciężki żółw o szorstkim pancerzu i długim, piłkowanym ogonie, leżący w mule stawów i wolno płynących rzek z wystawioną głową.';

  @override
  String get species_alligator_snapping_turtle_name => 'Skorpucha sępia';

  @override
  String get species_alligator_snapping_turtle_desc =>
      'Olbrzym o prehistorycznym wyglądzie, z trzema ząbkowanymi grzebieniami na pancerzu i przynętą w kształcie robaka na języku, czekający z otwartą paszczą na dnie rzek południa USA.';

  @override
  String get species_painted_turtle_name => 'Żółw malowany';

  @override
  String get species_painted_turtle_desc =>
      'Gładki ciemny żółw z czerwonymi i żółtymi paskami na szyi i brzegu pancerza, wygrzewający się rzędami na kłodach w całej Ameryce Północnej.';

  @override
  String get species_red_eared_slider_name => 'Żółw czerwonolicy';

  @override
  String get species_red_eared_slider_desc =>
      'Żółw wodny w zielone paski z czerwoną smugą za każdym okiem, popularny w handlu zoologicznym, dziś zdziczały w ciepłych wodach całego świata.';

  @override
  String get species_northern_map_turtle_name =>
      'Żółw mapowy (northern map turtle)';

  @override
  String get species_northern_map_turtle_desc =>
      'Oliwkowy żółw z żółtymi liniami na pancerzu przypominającymi mapę i z niskim kilem, wygrzewający się na skałach nad czystymi rzekami i dużymi jeziorami.';

  @override
  String get species_spiny_softshell_turtle_name => 'Żółwiak kolcowaty';

  @override
  String get species_spiny_softshell_turtle_desc =>
      'Płaski, skórzasty żółw podobny do naleśnika, z ryjkiem jak fajka, zagrzebany w piasku płytkich rzek tak, że widać tylko głowę.';

  @override
  String get species_florida_softshell_turtle_name => 'Żółwiak drapieżny';

  @override
  String get species_florida_softshell_turtle_desc =>
      'Duży ciemny żółwiak z długim, rurkowatym ryjkiem, pospolity w źródłach, kanałach i jeziorach Florydy.';

  @override
  String get species_pig_nosed_turtle_name => 'Miękkoskórek dwupazurzasty';

  @override
  String get species_pig_nosed_turtle_desc =>
      'Niezwykły żółw rzeczny Nowej Gwinei i północnej Australii o płetwach jak u żółwi morskich i mięsistym, świńskim ryjku.';

  @override
  String get species_mary_river_turtle_name =>
      'Żółw z rzeki Mary (Mary River turtle)';

  @override
  String get species_mary_river_turtle_desc =>
      'Rzadki australijski żółw, który oddycha przez kloakę i nosi zielony irokez z glonów; żyje w jednej tylko rzece w Queenslandzie.';

  @override
  String get species_yellow_spotted_river_turtle_name =>
      'Żółw rzeczny żółtoplamy (yellow-spotted river turtle)';

  @override
  String get species_yellow_spotted_river_turtle_desc =>
      'Amazoński żółw bokoszyjny z żółtymi plamami na głowie, wygrzewający się grupami na kłodach i łachach piaszczystych dużych rzek.';

  @override
  String get species_european_pond_turtle_name => 'Żółw błotny';

  @override
  String get species_european_pond_turtle_desc =>
      'Ciemny żółw nakrapiany żółtymi kropkami, rodzimy słodkowodny żółw Europy, zsuwający się z nasłonecznionych brzegów do zarośniętych stawów.';

  @override
  String get species_american_alligator_name => 'Aligator missisipski';

  @override
  String get species_american_alligator_desc =>
      'Opancerzony gad o szerokim pysku z bagien, źródeł i rzek południowo-wschodnich Stanów Zjednoczonych, unoszący się tak, że nad wodą widać tylko oczy i nozdrza.';

  @override
  String get species_spectacled_caiman_name => 'Kajman okularowy';

  @override
  String get species_spectacled_caiman_desc =>
      'Mały oliwkowy kajman z kostnym wałem między oczami, liczny w wolno płynących rzekach i lagunach Ameryki Środkowej i Południowej.';

  @override
  String get species_black_caiman_name => 'Kajman czarny';

  @override
  String get species_black_caiman_desc =>
      'Największy drapieżnik Amazonii, czarny opancerzony kajman długości do pięciu metrów, polujący nocą w jeziorach i zalanym lesie.';

  @override
  String get species_freshwater_crocodile_name => 'Krokodyl australijski';

  @override
  String get species_freshwater_crocodile_desc =>
      'Australijski krokodyl o wąskim pysku z północnych rzek i wąwozów, płochliwy i znacznie mniejszy od krokodyla różańcowego.';

  @override
  String get species_northern_water_snake_name => 'Zaskroniec północny';

  @override
  String get species_northern_water_snake_desc =>
      'Gruby brązowy wąż w poprzeczne pasy, wygrzewający się na skałach i gałęziach nad strumieniami wschodniej Ameryki Północnej; niejadowity, ale skory do kąsania.';

  @override
  String get species_green_anaconda_name => 'Anakonda zielona';

  @override
  String get species_green_anaconda_desc =>
      'Najcięższy wąż na Ziemi, oliwkowy olbrzym w czarne plamy, leżący w zanurzeniu na bagnach i w wolno płynących rzekach Amazonii.';

  @override
  String get species_hellbender_name => 'Skrytoskrzel';

  @override
  String get species_hellbender_desc =>
      'Olbrzymia salamandra o płaskiej głowie i pomarszczonych fałdach skóry, kryjąca się pod dużymi głazami w zimnych, czystych rzekach Appalachów.';

  @override
  String get species_mudpuppy_name => 'Odmieniec amerykański';

  @override
  String get species_mudpuppy_desc =>
      'Brązowa, plamista salamandra, która przez całe życie zachowuje pierzaste czerwone skrzela i nocą pełza po dnie jezior i rzek.';

  @override
  String get species_axolotl_name => 'Ambystoma meksykańska';

  @override
  String get species_axolotl_desc =>
      'Uśmiechnięta salamandra ze skrzelami, która nigdy nie opuszcza wody, krytycznie zagrożona w kanałach Xochimilco pod miastem Meksyk.';

  @override
  String get species_chinese_giant_salamander_name =>
      'Salamandra olbrzymia chińska';

  @override
  String get species_chinese_giant_salamander_desc =>
      'Największy żyjący płaz, pomarszczony brązowy olbrzym długości prawie dwóch metrów, kryjący się w chłodnych, kamienistych górskich potokach.';

  @override
  String get species_smooth_newt_name => 'Traszka zwyczajna';

  @override
  String get species_smooth_newt_desc =>
      'Mała oliwkowa traszka, co wiosnę wracająca do stawów; samcom wyrasta falisty grzebień, a ich pomarańczowy brzuch pokrywają plamy.';

  @override
  String get species_great_crested_newt_name => 'Traszka grzebieniasta';

  @override
  String get species_great_crested_newt_desc =>
      'Duża czarna, brodawkowata traszka o ognistopomarańczowym brzuchu; samce w porze godowej noszą postrzępiony, smoczy grzebień.';

  @override
  String get species_american_bullfrog_name => 'Żaba rycząca';

  @override
  String get species_american_bullfrog_desc =>
      'Ogromna zielona żaba o basowym ryku, siedząca wśród liści lilii wodnych w ciepłych stawach, dziś inwazyjna na kilku kontynentach.';

  @override
  String get species_common_frog_name => 'Żaba trawna';

  @override
  String get species_common_frog_desc =>
      'Brązowa żaba z ciemną maską przy oczach, wiosną zbierająca się w hałaśliwe gromady, by składać skrzek w stawach i rowach Europy.';

  @override
  String get species_north_american_river_otter_name => 'Wydrak kanadyjski';

  @override
  String get species_north_american_river_otter_desc =>
      'Smukła, skora do zabawy wydra polująca na ryby i raki w rzekach i jeziorach Ameryki Północnej, zostawiająca na brzegach błotne ślizgawki.';

  @override
  String get species_eurasian_otter_name => 'Wydra europejska';

  @override
  String get species_eurasian_otter_desc =>
      'Płochliwa brązowa wydra rzek, jezior i wybrzeży Europy, po dziesięcioleciach spadku liczebności odradzająca się w całym swoim zasięgu.';

  @override
  String get species_giant_otter_name => 'Arirania amazońska';

  @override
  String get species_giant_otter_desc =>
      'Niemal dwumetrowa wydra z kremową plamą na gardle, żyjąca w hałaśliwych grupach rodzinnych na rzekach i starorzeczach Amazonii.';

  @override
  String get species_north_american_beaver_name => 'Bóbr kanadyjski';

  @override
  String get species_north_american_beaver_desc =>
      'Duży gryzoń o płaskim ogonie, który tamami spiętrza strumienie w stawy i pływa pod lodem, a schronienie znajduje w żeremiu z gałęzi.';

  @override
  String get species_eurasian_beaver_name => 'Bóbr europejski';

  @override
  String get species_eurasian_beaver_desc =>
      'Największy gryzoń Europy, reintrodukowany na całym kontynencie, ścinający nadrzeczne drzewa i budujący tamy oraz żeremia.';

  @override
  String get species_muskrat_name => 'Piżmak amerykański';

  @override
  String get species_muskrat_desc =>
      'Brązowy gryzoń wielkości szczura o łuskowatym, spłaszczonym ogonie, pływający wśród szuwarów pałkowych i budujący kopulaste domki z trzciny.';

  @override
  String get species_platypus_name => 'Dziobak australijski';

  @override
  String get species_platypus_desc =>
      'Jajorodny ssak z kaczym dziobem i błonami pławnymi na łapach, o świcie i zmierzchu żerujący z zamkniętymi oczami w potokach wschodniej Australii.';

  @override
  String get species_amazonian_manatee_name => 'Manat rzeczny';

  @override
  String get species_amazonian_manatee_desc =>
      'Najmniejszy z manatów, gładki ciemny roślinożerca z białą plamą na piersi, skubiący rośliny wodne w jeziorach i rzekach Amazonii.';

  @override
  String get species_amazon_river_dolphin_name => 'Inia amazońska';

  @override
  String get species_amazon_river_dolphin_desc =>
      'Różowy delfin o długim dziobie i giętkiej szyi, lawirujący między pniami zalanego lasu w dorzeczach Amazonki i Orinoko.';

  @override
  String get species_baikal_seal_name => 'Nerpa bajkalska';

  @override
  String get species_baikal_seal_desc =>
      'Jedyna na świecie foka słodkowodna, mała i srebrzystoszara, wylegująca się na lodzie i skalistych brzegach Bajkału.';

  @override
  String get species_capybara_name => 'Kapibara wielka';

  @override
  String get species_capybara_desc =>
      'Największy gryzoń, beczkowaty roślinożerca, który w spokojnych stadach brodzi i pływa w rzekach i na mokradłach Ameryki Południowej.';

  @override
  String get species_hippopotamus_name => 'Hipopotam nilowy';

  @override
  String get species_hippopotamus_desc =>
      'Potężny olbrzym afrykańskich rzek, który spędza dzień w zanurzeniu w stadzie i raczej chodzi po dnie, niż pływa; zbliżanie się do niego jest niebezpieczne.';

  @override
  String get species_white_water_lily_name => 'Grzybienie białe';

  @override
  String get species_white_water_lily_desc =>
      'Okrągłe pływające liście i duże białe kwiaty wyrastające z grubych kłączy zakorzenionych w mule stojących wód Europy.';

  @override
  String get species_yellow_pond_lily_name => 'Grążel żółty';

  @override
  String get species_yellow_pond_lily_desc =>
      'Sercowate pływające liście i kubkowate żółte kwiaty, a pod wodą duże, prześwitujące liście podwodne, które nurkowie widzą od spodu.';

  @override
  String get species_american_eelgrass_name => 'Nurzaniec amerykański';

  @override
  String get species_american_eelgrass_desc =>
      'Taśmowate liście długości do dwóch metrów, falujące w prądzie czystych rzek i źródeł, przysmak manatów.';

  @override
  String get species_coontail_name => 'Rogatek sztywny';

  @override
  String get species_coontail_desc =>
      'Zanurzona roślina bez korzeni, z okółkami sztywnych, widlasto rozgałęzionych liści przypominającymi ogon szopa, unosząca się gęstymi kłębami w stojącej wodzie.';

  @override
  String get species_eurasian_watermilfoil_name => 'Wywłócznik kłosowy';

  @override
  String get species_eurasian_watermilfoil_desc =>
      'Pierzasta roślina zanurzona z okółkami drobno podzielonych liści, tworząca przy powierzchni gęste kożuchy, inwazyjna w wielu jeziorach.';

  @override
  String get species_muskgrass_name => 'Ramienica pospolita';

  @override
  String get species_muskgrass_desc =>
      'Krucha zielenica o piżmowym zapachu i okółkowych gałązkach, często inkrustowana wapieniem, wyścielająca dno czystych jezior o twardej wodzie.';

  @override
  String get species_canadian_waterweed_name => 'Moczarka kanadyjska';

  @override
  String get species_canadian_waterweed_desc =>
      'Gęsta roślina zanurzona z okółkami trzech małych ciemnozielonych liści, rozprzestrzeniająca się z fragmentów pędów w chłodnych jeziorach i kanałach całego świata.';

  @override
  String get species_curly_leaf_pondweed_name => 'Rdestnica kędzierzawa';

  @override
  String get species_curly_leaf_pondweed_desc =>
      'Roślina zanurzona o czerwonawozielonych liściach z falistym brzegiem, podobnych do pomarszczonej lasagne, rosnąca wczesną wiosną przed innymi roślinami wodnymi.';

  @override
  String get species_water_hyacinth_name => 'Pontederia gruboogonkowa';

  @override
  String get species_water_hyacinth_desc =>
      'Roślina pływająca o lśniących liściach na wypełnionych powietrzem ogonkach i kłosach lawendowych kwiatów, zarastająca ciepłe drogi wodne na całym świecie.';

  @override
  String get species_common_reed_name => 'Trzcina pospolita';

  @override
  String get species_common_reed_desc =>
      'Wysoka trawa o pierzastych wiechach, tworząca gęste łany wzdłuż brzegów jezior; jej zanurzone łodygi dają schronienie narybkowi i larwom ważek.';

